import AppIntents
import Foundation
import HermesGatewayKit

// D7: Shortcuts actions. "Ask Bot" sends a prompt to a bot's Bot Chat and returns the reply text (with a
// timeout); "Send to Group Chat" posts a message to a room. Both run inside the running app, through its
// models (`AppModel.quickSender`): Hermes Bot must be running and connected to Hermes. Shortcuts launches
// the app when it is not running; the action then waits up to `connectWait` for the connection.
// The App Intents metadata Shortcuts reads is generated by scripts/package-app.sh (appintentsmetadataprocessor).

/// The intents' logic, headless (IntentRunnerTests): waits for the connection, then sends.
@MainActor
struct IntentRunner {
    var sender: () -> QuickSender
    /// How long an action waits for the app to finish connecting (a launch by Shortcuts).
    var connectWait: TimeInterval = 20
    var step: UInt64 = 200_000_000

    static let live = IntentRunner(sender: { AppModel.shared.quickSender })

    /// The default reply timeout, and its bounds.
    static let defaultTimeout = 120
    static let timeoutRange = 5...900

    func waitForConnection() async throws -> QuickSender {
        let deadline = Date().addingTimeInterval(connectWait)
        while true {
            let s = sender()
            if s.connected() { return s }
            guard Date() < deadline, !Task.isCancelled else { throw QuickSendError.notConnected }
            try? await Task.sleep(nanoseconds: step)
        }
    }

    func ask(bot: String, prompt: String, timeout: Int) async throws -> String {
        let s = try await waitForConnection()
        let turn = try await s.send(prompt, toBot: bot)
        let seconds = min(max(timeout, Self.timeoutRange.lowerBound), Self.timeoutRange.upperBound)
        return try await s.reply(turn, timeout: TimeInterval(seconds))
    }

    func post(room: String, message: String) async throws {
        try await waitForConnection().send(message, toRoom: room)
    }

    func bots() async -> [Bot] { (try? await waitForConnection())?.bots() ?? [] }
    func rooms() async -> [RoomSummary] { (try? await waitForConnection())?.rooms() ?? [] }
}

// MARK: - entities

struct BotEntity: AppEntity {
    static let typeDisplayRepresentation: TypeDisplayRepresentation = "Bot"
    static let defaultQuery = BotEntityQuery()

    let id: String
    let title: String

    var displayRepresentation: DisplayRepresentation { DisplayRepresentation(title: "\(title)") }

    init(id: String, title: String) { self.id = id; self.title = title }
    init(_ bot: Bot) { self.init(id: bot.name, title: bot.title) }
}

struct BotEntityQuery: EntityQuery {
    func entities(for identifiers: [String]) async throws -> [BotEntity] {
        let bots = await IntentRunner.live.bots()
        return identifiers.compactMap { id in bots.first { $0.name == id }.map(BotEntity.init) }
    }

    func suggestedEntities() async throws -> [BotEntity] {
        await IntentRunner.live.bots().map(BotEntity.init)
    }
}

struct RoomEntity: AppEntity {
    static let typeDisplayRepresentation: TypeDisplayRepresentation = "Group Chat"
    static let defaultQuery = RoomEntityQuery()

    let id: String
    let name: String

    var displayRepresentation: DisplayRepresentation { DisplayRepresentation(title: "\(name)") }

    init(id: String, name: String) { self.id = id; self.name = name }
    init(_ room: RoomSummary) { self.init(id: room.roomId, name: room.name) }
}

struct RoomEntityQuery: EntityQuery {
    func entities(for identifiers: [String]) async throws -> [RoomEntity] {
        let rooms = await IntentRunner.live.rooms()
        return identifiers.compactMap { id in rooms.first { $0.roomId == id }.map(RoomEntity.init) }
    }

    func suggestedEntities() async throws -> [RoomEntity] {
        await IntentRunner.live.rooms().map(RoomEntity.init)
    }
}

// MARK: - intents

struct AskBotIntent: AppIntent {
    static let title: LocalizedStringResource = "Ask Bot"
    static let description = IntentDescription(
        "Sends a message to a bot's Bot Chat in Hermes Bot and returns its reply. Hermes Bot must be running and connected.")

    @Parameter(title: "Bot")
    var bot: BotEntity

    @Parameter(title: "Message", inputOptions: String.IntentInputOptions(multiline: true))
    var message: String

    @Parameter(title: "Timeout (seconds)", default: 120, inclusiveRange: (5, 900))
    var timeout: Int

    static var parameterSummary: some ParameterSummary {
        Summary("Ask \(\.$bot) \(\.$message)") { \.$timeout }
    }

    @MainActor
    func perform() async throws -> some IntentResult & ReturnsValue<String> {
        let reply = try await IntentRunner.live.ask(bot: bot.id, prompt: message, timeout: timeout)
        return .result(value: reply)
    }
}

struct SendToGroupChatIntent: AppIntent {
    static let title: LocalizedStringResource = "Send to Group Chat"
    static let description = IntentDescription(
        "Posts a message to a group chat in Hermes Bot. Hermes Bot must be running and connected.")

    @Parameter(title: "Group Chat")
    var room: RoomEntity

    @Parameter(title: "Message", inputOptions: String.IntentInputOptions(multiline: true))
    var message: String

    static var parameterSummary: some ParameterSummary {
        Summary("Send \(\.$message) to \(\.$room)")
    }

    @MainActor
    func perform() async throws -> some IntentResult {
        try await IntentRunner.live.post(room: room.id, message: message)
        return .result()
    }
}
